-- Story 15.3 (UC-CHK-002) submit-gate fixtures: three Draft + all-ten-MET mills and one status-only
-- mill, all reporting year 2021, all ACT, Draft on BOTH tracks, REPORT_COMPLETED_IND 'N', and the eleven
-- ILCR_REPORT_CATEGORY rows at 'D' that the open-year path (ReportingYearService.CATEGORY_IDS) would have
-- written -- no other test migration seeds a single category row, and legacy NPEs without one.
--
-- Every Schedules 1-10 check is MET on 780/781/782 with the smallest document that passes:
--   Sch 1 = mill 528's complete document (V7:11-24): the thirteen checked items with VOLUME and/or COST
--           plus one item-19 Other-Costs row at VOLUME 0 (a zero-other-costs schedule passes);
--   Sch 2 = mill 621's item-25 cost (V10:50);
--   Sch 3 = mill 572's complete document (V18:38-59): harvest 1000 >= PO&P 500 per pair, volumes on 118/119;
--   Schedules 4-10 are vacuously MET with zero rows (their checks start met = true).
-- One mill per mutating test, because a submit moves the row D -> S:
--   780  CheckStatusSubmitIT            -- AC 1 happy path (submitted once, asserted per column)
--   781  CheckStatusSubmitConcurrencyIT -- AC 6 two racing submits, exactly one commits
--   782  CheckStatusSubmitIT            -- AC 7 rollback: the test deletes its category row '7' first
--   783  DraftGateLockIT                -- D8 (a'): status row + two EMPTY summaries, every converted gate blocks behind its lock
--
-- Prefix 55 is BELOW 70 so R__70's set-based insert associates the canonical submitter to all four mills.
-- This file also seeds the e2e database (same db/ chain + db-e2e/R__80), so these mills appear in the e2e
-- Home dropdown as "1780 Submit All Met Milling 2021" etc. MILL_NUMBER is 1780-1783 (e2e mill 9050 'WESTEROS'
-- carries 760, db-e2e/R__80:109, and R__60's Data Extract mills carry 7600-7620; the dropdown shows number + name).
-- The block was 760-763 while this story was in development; it moved to 780-783 at the merge with main because
-- R__60_data_extract_fixtures.sql (Stories 21.1/21.2) had claimed 760-762 and summaries 1300-1399 in the meantime.
--
-- Claims (verified free by grep over db/*.sql and db-e2e/*.sql on 2026-09-15): MILL / ILCR_MILL_STATUS_XREF
-- 780-783 (MILL_NUMBER 1780-1783), ILCR_REPORT_SUMMARY 1400-1410, ILCR_COST_REPORT_DETAIL 5600-5707 (block
-- 5600-5729 reserved). Every INSERT is guarded by WHERE NOT EXISTS on its key (the R__51 idiom) so a
-- checksum change re-applies cleanly; see README convention 1b for what that guard does and does not do. Every
-- statement is the single-row `(cols) SELECT ... FROM DUAL WHERE NOT EXISTS` form the e2e seed-parity gate reads.
-- ================================================================================================
-- Mill 780 -- Submit All Met Milling (MILL_NUMBER 1780). Summaries 1400-1402, details 5600-5635.
-- ================================================================================================
INSERT INTO THE.MILL (MILL_ID, MILL_NAME, MILL_NUMBER, ENTRY_USERID)
  SELECT 780, 'Submit All Met Milling', 1780, 'SEED' FROM DUAL
   WHERE NOT EXISTS (SELECT 1 FROM THE.MILL WHERE MILL_ID = 780);
INSERT INTO THE.ILCR_MILL_STATUS_XREF (ILCR_MILL_STATUS_XREF_ID, ILCR_MILL_STATUS_CODE, ENTRY_USERID)
  SELECT 780, 'ACT', 'SEED' FROM DUAL
   WHERE NOT EXISTS (SELECT 1 FROM THE.ILCR_MILL_STATUS_XREF WHERE ILCR_MILL_STATUS_XREF_ID = 780);
INSERT INTO THE.ILCR_MILL_REPORT_STATUS (REPORT_YEAR, ILCR_MILL_ID, ILCR_MILL_REPORT_STATUS_CODE,
                                         MILL_SILVICULTUR_STATUS_CODE, REPORT_COMPLETED_IND, REVISION_COUNT,
                                         ENTRY_USERID, ENTRY_TIMESTAMP, UPDATE_USERID, UPDATE_TIMESTAMP)
  SELECT 2021, 780, 'D', 'D', 'N', 0, 'SEED', SYSTIMESTAMP, 'SEED', SYSTIMESTAMP FROM DUAL
   WHERE NOT EXISTS (SELECT 1 FROM THE.ILCR_MILL_REPORT_STATUS WHERE REPORT_YEAR = 2021 AND ILCR_MILL_ID = 780);
INSERT INTO THE.ILCR_REPORT_CATEGORY (REPORT_YEAR, ILCR_MILL_ID, ILCR_CATEGORY_ID, CATEGORY_STATE_CODE,
                                      REPORTABLE_DETAIL_IND, REVISION_COUNT, ENTRY_USERID, ENTRY_TIMESTAMP,
                                      UPDATE_USERID, UPDATE_TIMESTAMP)
  SELECT 2021, 780, c.ID, 'D', 'Y', 0, 'SEED', SYSDATE, 'SEED', SYSDATE
    FROM (SELECT '1' ID FROM DUAL UNION ALL SELECT '2' FROM DUAL UNION ALL SELECT '3' FROM DUAL
          UNION ALL SELECT '4' FROM DUAL UNION ALL SELECT '5' FROM DUAL UNION ALL SELECT '6' FROM DUAL
          UNION ALL SELECT '7' FROM DUAL UNION ALL SELECT '8' FROM DUAL UNION ALL SELECT '9' FROM DUAL
          UNION ALL SELECT '10' FROM DUAL UNION ALL SELECT '11' FROM DUAL) c
   WHERE NOT EXISTS (SELECT 1 FROM THE.ILCR_REPORT_CATEGORY r
                      WHERE r.REPORT_YEAR = 2021 AND r.ILCR_MILL_ID = 780 AND r.ILCR_CATEGORY_ID = c.ID);
